{"implementation":"def solve(case):
    import math

    if not isinstance(case, dict):
        raise ValueError('case must be an object')
    if 'nodes' not in case or 'required_symbols' not in case:
        raise ValueError('missing required case field')
    if '_case_nonce' in case and not isinstance(case['_case_nonce'], str):
        raise ValueError('invalid case nonce')

    nodes = case['nodes']
    required_symbols = case['required_symbols']
    if not isinstance(nodes, list) or not nodes:
        raise ValueError('nodes must be a nonempty array')
    if not isinstance(required_symbols, list) or any(not isinstance(s, str) for s in required_symbols):
        raise ValueError('required_symbols must be an array of strings')

    required_fields = ('id', 'parent', 'symbol', 'depth', 'removable', 'utility')
    by_id = {}
    roots = []
    for node in nodes:
        if not isinstance(node, dict) or any(field not in node for field in required_fields):
            raise ValueError('invalid node')
        node_id = node['id']
        parent = node['parent']
        depth = node['depth']
        utility = node['utility']
        if not isinstance(node_id, str) or node_id in by_id:
            raise ValueError('node ids must be unique strings')
        if parent is not None and not isinstance(parent, str):
            raise ValueError('invalid parent')
        if not isinstance(node['symbol'], str):
            raise ValueError('invalid symbol')
        if isinstance(depth, bool) or not isinstance(depth, int) or depth < 0:
            raise ValueError('invalid depth')
        if not isinstance(node['removable'], bool):
            raise ValueError('invalid removable flag')
        if isinstance(utility, bool) or not isinstance(utility, (int, float)) or not math.isfinite(utility):
            raise ValueError('invalid utility')
        by_id[node_id] = node
        if parent is None:
            roots.append(node_id)

    if len(roots) != 1:
        raise ValueError('tree must have exactly one root')
    root_id = roots[0]
    if by_id[root_id]['depth'] != 0:
        raise ValueError('root depth must be zero')

    children = {node_id: [] for node_id in by_id}
    for node_id, node in by_id.items():
        parent = node['parent']
        if parent is None:
            continue
        if parent not in by_id or parent == node_id:
            raise ValueError('invalid parent reference')
        if node['depth'] != by_id[parent]['depth'] + 1:
            raise ValueError('inconsistent tree depth')
        children[parent].append(node_id)

    present_symbols = {node['symbol'] for node in nodes}
    if any(symbol not in present_symbols for symbol in required_symbols):
        raise ValueError('required symbol is absent')

    retained = set(by_id)
    removed = []
    candidates = sorted(nodes, key=lambda node: (-node['depth'], node['id']))
    for node in candidates:
        node_id = node['id']
        if node_id == root_id or not node['removable'] or node['symbol'] in required_symbols:
            continue
        if any(child in retained for child in children[node_id]):
            continue
        remaining_symbols = {by_id[item]['symbol'] for item in retained if item != node_id}
        if any(symbol not in remaining_symbols for symbol in required_symbols):
            continue
        retained.remove(node_id)
        removed.append(node_id)

    return {
        'removed_node_ids': removed,
        'retained_node_ids': sorted(retained),
    }
